function addSensor(id, name, unit, devClass, stateClass, valTemplate, precision) {
    const payload = {
        name: name, 
        has_entity_name: true,
        unique_id: `${bmsName}_${id}`,
        state_topic: stateTopic,
        value_template: valTemplate || `{{ value_json.${id} }}`,
        unit_of_measurement: unit,
        device_class: devClass,
        state_class: stateClass,
        device: device
    };

    if (precision !== undefined) payload.suggested_display_precision = precision;

    configs.push({
        topic: `homeassistant/sensor/${bmsName}/${id}/config`,
        payload: payload
    });
}

function addBinary(id, name, devClass, valTemplate) {
    configs.push({
        topic: `homeassistant/binary_sensor/${bmsName}/${id}/config`,
        payload: {
            name: name,
            has_entity_name: true,
            unique_id: `${bmsName}_${id}`,
            state_topic: stateTopic,
            value_template: valTemplate || `{{ value_json.${id} }}`,
            payload_on: "ON",
            payload_off: "OFF",
            device_class: devClass,
            device: device
        }
    });
}

// 1. Pack-Level Metrics
addSensor("voltage", "Voltage", "V", "voltage", "measurement", null, 2);
addSensor("current", "Current", "A", "current", "measurement", null, 2);
addSensor("power", "Power", "W", "power", "measurement", null, 1);
addSensor("soc", "Soc", "%", "battery", "measurement");
