addSensor("cell_index_min", "Cell Index min", null, null, null);
addSensor("cell_index_max", "Cell Index max", null, null, null);

// 3. Temperatures 
addSensor("temp_cell_1", "Cell Temp 1", "°C", "temperature", "measurement", null, 1);
addSensor("temp_cell_2", "Cell Temp 2", "°C", "temperature", "measurement", null, 1);
addSensor("temp_cell_3", "Cell Temp 3", "°C", "temperature", "measurement", null, 1);
