addSensor("temp_ambient", "Ambient Temp", "°C", "temperature", "measurement", null, 1);
addSensor("temp_mos", "MOS Temp", "°C", "temperature", "measurement", null, 1);

// 4. Cumulative Energy Metrics
addSensor("total_energy_netted", "total energy netted", "kWh", "energy", "total");
addSensor("total_energy_input", "total energy input", "kWh", "energy", "total_increasing");
addSensor("total_energy_output", "total energy output", "kWh", "energy", "total_increasing");
addSensor("total_charge_netted", "total charge netted", "Ah", null, "total");

// 5. Status, Health & Balancing
addBinary("balancing", "Balancing", null);
addSensor("balancing_cells", "Balancing Cells", null, null, null);
addBinary("problem", "Problem", "problem");
addSensor("problem_code", "Problem Code", null, null, null);
addSensor("soh", "State of Health", "%", null, "measurement");
addBinary("charge_switch", "Charge Switch", null);
addBinary("discharge_switch", "Discharge Switch", null);

return [configs.map(c => ({ topic: c.topic, payload: JSON.stringify(c.payload), retain: true }))];

const bmsName = "battery_2"; // Change to battery_2 for the second flow
const stateTopic = `homeassistant/${bmsName}/protection`;

// We inject the parsed data object directly into the script to read the keys
const keys = [
    "cell_ov_alarm", "cell_ov_alarm_recov", "cell_ov_alarm_delay", "cell_ov_prot", "cell_ov_prot_recov", "cell_ov_prot_delay",
    "cell_uv_alarm", "cell_uv_alarm_recov", "cell_uv_alarm_delay", "cell_uv_prot", "cell_uv_prot_recov", "cell_uv_prot_delay",
    "pack_ov_alarm", "pack_ov_alarm_recov", "pack_ov_alarm_delay", "pack_ov_prot", "pack_ov_prot_recov", "pack_ov_prot_delay",
    "pack_uv_alarm", "pack_uv_alarm_recov", "pack_uv_alarm_delay", "pack_uv_prot", "pack_uv_prot_recov", "pack_uv_prot_delay",
    "chg_oc_alarm", "chg_oc_alarm_delay", "chg_oc_prot", "chg_oc_prot_delay", "chg_oc_recov_delay", "chg_oc_lock_times",
    "chg_oc2_prot", "chg_oc2_prot_delay", "chg_oc2_recov_delay",
    "dsg_oc_alarm", "dsg_oc_alarm_delay", "dsg_oc_prot", "dsg_oc_prot_delay", "dsg_oc_recov_delay", "dsg_oc_lock_times",
    "dsg_oc2_prot", "dsg_oc2_prot_delay", "dsg_oc2_recov_delay",
    "chg_ot_alarm", "chg_ot_alarm_recov", "chg_ot_prot", "chg_ot_prot_recov",
    "chg_ut_alarm", "chg_ut_alarm_recov", "chg_ut_prot", "chg_ut_prot_recov",
    "dsg_ot_alarm", "dsg_ot_alarm_recov", "dsg_ot_prot", "dsg_ot_prot_recov",
    "dsg_ut_alarm", "dsg_ut_alarm_recov", "dsg_ut_prot", "dsg_ut_prot_recov",
    "mos_ot_alarm", "mos_ot_alarm_recov", "mos_ot_prot", "mos_ot_prot_recov",
    "ambient_ot_alarm", "ambient_ot_alarm_recov", "ambient_ot_prot", "ambient_ot_prot_recov",
    "volt_diff_alarm", "volt_diff_alarm_recov", "volt_diff_prot", "volt_diff_prot_recov",
    "soc_low_alarm", "soc_low_alarm_recov"
];

const msgs = [];

keys.forEach(key => {
    let unit = "";
    if (key.includes("cell_") || key.includes("volt_diff")) unit = "mV";
    if (key.includes("pack_")) unit = "V";
    if (key.includes("_oc")) unit = "A";
    if (key.includes("_ot") || key.includes("_ut")) unit = "°C";
    if (key.includes("delay") || key.includes("lock") || key.includes("recov_delay")) unit = "ms";
    if (key === "soc_low_alarm" || key === "soc_low_alarm_recov") unit = "%";

    // Clean up the name for the UI (e.g. "cell_ov_alarm" -> "Cell Ov Alarm")
    const friendlyName = key.split('_').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');

    const payload = {
        name: `${friendlyName}`,
        state_topic: stateTopic,
        value_template: `{{ value_json.${key} }}`,
        unique_id: `${bmsName}_${key}`,
        device: {
            identifiers: [bmsName],
            name: bmsName,
            manufacturer: "JBD"
        },
        entity_category: "diagnostic" // Maps to the Diagnostic block in HA
    };

    if (unit) payload.unit_of_measurement = unit;

    msgs.push({
        topic: `homeassistant/sensor/${bmsName}/${key}/config`,
        payload: payload,
        retain: true
    });
});

return [msgs];

